const item = $input.item.json;
const _airtableRecordId = $input.item.json.id || $input.item.id || '';
const rawUrl = item['URL'] || '';
const platform = (item['Platform'] || '').toLowerCase();
const channelId = item['Channel ID'] || '';

let url = rawUrl.split('?')[0].replace(/\/$/, '');
url = url.replace('/reel/', '/reels/');

let identifier = '', identifierType = '';

if (platform === 'youtube' || rawUrl.includes('youtube.com') || rawUrl.includes('youtu.be')) {
  if (rawUrl.includes('watch?v=')) { identifier = rawUrl.split('watch?v=')[1].split('&')[0]; identifierType = 'video'; }
  else if (url.includes('shorts/')) { identifier = url.split('shorts/')[1].split('?')[0]; identifierType = 'video'; }
  else if (rawUrl.includes('youtu.be/')) { identifier = rawUrl.split('youtu.be/')[1].split('?')[0]; identifierType = 'video'; }
} else if (platform === 'instagram' || url.includes('instagram.com')) {
  const match = url.match(/\/(reels?|p|tv)\/([^/?]+)/);
  identifier = match ? match[2] : '';
  identifierType = 'post';
} else if (platform === 'tiktok' || url.includes('tiktok.com')) {
  if (url.includes('/video/')) { identifier = url.split('/video/')[1].split('?')[0]; identifierType = 'video'; }
}

if (!identifier) {
  return { json: { skip: true, _airtableRecordId, reason: 'Cannot parse URL: ' + rawUrl } };
}

return { json: {
  skip: false,
  _airtableRecordId,
  platform: item['Platform'] || '',
  identifier,
  identifierType,
  url: rawUrl,
  rawUrl,
  channelId,
  _batchIndex: $input.item.index || 0,
  existingOutlierScore: item['Outlier Score'] || 0,
  existingViewCount: item['View Count'] || 0,
  existingLikeCount: item['Like Count'] || 0,
  existingCommentCount: item['Comment Count'] || 0,
  existingDuration: item['Duration'] || 0,
  existingCreatorHandle: item['Creator_Handle'] || ''
}};

const p = $input.item.json;
const platform = (p.platform || '').toLowerCase();
const MAX_SUPADATA_CALLS = 25;

// YouTube uses Google API — no Supadata cost, always allow
if (platform === 'youtube') {
  return { json: { ...p, _allowApi: true } };
}

// For TikTok/Instagram — check if ONLY Creator_Handle is missing
// If so, skip the API entirely — not worth a credit for just the handle
const missingView = !p.existingViewCount || p.existingViewCount === 0;
const missingLike = !p.existingLikeCount || p.existingLikeCount === 0;
const missingComment = !p.existingCommentCount || p.existingCommentCount === 0;
const missingDuration = !p.existingDuration || p.existingDuration === 0;
const missingHandle = !p.existingCreatorHandle || p.existingCreatorHandle === '';

const onlyHandleMissing = missingHandle && !missingView && !missingLike && !missingComment && !missingDuration;

if (onlyHandleMissing) {
  return { json: { 
    ...p, 
    _allowApi: false, 
    _reason: 'Only Creator_Handle missing — skipping Supadata call'
  }};
}

// Hard cap on Supadata calls per run
const batchIndex = p._batchIndex || 0;
if (batchIndex >= MAX_SUPADATA_CALLS) {
  return { json: { 
    ...p, 
    _allowApi: false, 
    _reason: 'Supadata cap reached (' + MAX_SUPADATA_CALLS + ' calls/run)'
  }};
}

return { json: { ...p, _allowApi: true } };

// YouTube Data API response parser
const item = $input.item.json;
const _airtableRecordId = $('5. Parse URL').item.json._airtableRecordId || '';
const parsed = $('5. Parse URL').item.json;

const ytItems = item.items || [];
const yt = ytItems[0] || null;

const fields = {};

if (yt) {
  const stats = yt.statistics || {};
  const snippet = yt.snippet || {};
  const contentDetails = yt.contentDetails || {};

  const existingVC = parsed.existingViewCount;
  if (!existingVC || existingVC === 0 || existingVC === '' || existingVC === null) {
    const v = parseInt(stats.viewCount || 0);
    if (v > 0) fields['View Count'] = v;
  }

  const existingLC = parsed.existingLikeCount;
  if (!existingLC || existingLC === 0 || existingLC === '' || existingLC === null) {
    const l = parseInt(stats.likeCount || 0);
    if (l > 0) fields['Like Count'] = l;
  }

  const existingCC = parsed.existingCommentCount;
  if (!existingCC || existingCC === 0 || existingCC === '' || existingCC === null) {
    const c = parseInt(stats.commentCount || 0);
    if (c > 0) fields['Comment Count'] = c;
  }

  const existingDur = parsed.existingDuration;
  if (!existingDur || existingDur === 0 || existingDur === '' || existingDur === null) {
    const dur = contentDetails.duration || 'PT0S';
    let s = 0;
    const m = dur.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
    if (m) s = (parseInt(m[1]||0)*3600)+(parseInt(m[2]||0)*60)+parseInt(m[3]||0);
    if (s > 0) fields['Duration'] = s;
  }

  const existingHandle = parsed.existingCreatorHandle;
  if (!existingHandle || existingHandle === '' || existingHandle === null) {
    try {
      const channelItems = $('8a2. Fetch YouTube Channel Handle').item.json.items || [];
      const channelSnippet = (channelItems[0] || {}).snippet || {};
      const handle = channelSnippet.customUrl || '';
      if (handle) fields['Creator_Handle'] = handle.startsWith('@') ? handle : '@' + handle;
    } catch(e) {}
  }

  const isUpdatingStats = fields['View Count'] !== undefined || fields['Like Count'] !== undefined || fields['Comment Count'] !== undefined;
  if (isUpdatingStats) {
    const viewCount = fields['View Count'] || parsed.existingViewCount || 0;
    if (viewCount > 0) {
      fields['Outlier Score'] = Math.round((viewCount / 10000) * 100) / 100;
    }
  }
}

const hasFieldsToUpdate = Object.keys(fields).length > 0;

return { json: {
  ...item,
  _airtableRecordId,
  _skipUpdate: !hasFieldsToUpdate,
  _reason: hasFieldsToUpdate ? 'Has fields to update' : 'No missing fields to fill',
  _fields: fields
}};

// Supadata response parser for TikTok & Instagram
const item = $input.item.json;
const raw = item;
const stats = raw.stats || {};
const media = raw.media || {};
const author = raw.author || {};

const _airtableRecordId = $('5. Parse URL').item.json._airtableRecordId || '';
const parsed = $('5. Parse URL').item.json;

const fields = {};

if (!parsed.existingViewCount || parsed.existingViewCount === 0) {
  const v = parseInt(stats.views || stats.viewCount || stats.play_count || 0);
  if (v > 0) fields['View Count'] = v;
}

if (!parsed.existingLikeCount || parsed.existingLikeCount === 0) {
  const l = parseInt(stats.likes || stats.likeCount || stats.digg_count || 0);
  if (l > 0) fields['Like Count'] = l;
}

if (!parsed.existingCommentCount || parsed.existingCommentCount === 0) {
  const c = stats.comments !== undefined ? parseInt(stats.comments) :
            stats.commentCount !== undefined ? parseInt(stats.commentCount) :
            stats.comment_count !== undefined ? parseInt(stats.comment_count) : null;
  if (c !== null) fields['Comment Count'] = c;
}

if (!parsed.existingDuration || parsed.existingDuration === 0) {
  const d = parseInt(media.duration || raw.duration || 0);
  if (d > 0) fields['Duration'] = d;
}

if (!parsed.existingCreatorHandle || parsed.existingCreatorHandle === '') {
  const handle = author.uniqueId || author.username || raw.authorUniqueId || raw.ownerUsername || raw.channelHandle || '';
  if (handle) fields['Creator_Handle'] = handle.startsWith('@') ? handle : '@' + handle;
}

const isUpdatingStats = fields['View Count'] !== undefined || fields['Like Count'] !== undefined || fields['Comment Count'] !== undefined;
if (isUpdatingStats) {
  const viewCount = fields['View Count'] || parsed.existingViewCount || 0;
  if (viewCount > 0) {
    fields['Outlier Score'] = Math.round((viewCount / 10000) * 100) / 100;
  }
}

const hasFieldsToUpdate = Object.keys(fields).length > 0;

return { json: {
  ...item,
  _airtableRecordId,
  _skipUpdate: !hasFieldsToUpdate,
  _reason: hasFieldsToUpdate ? 'Has fields to update' : 'No missing fields to fill',
  _fields: fields
}};

const item = $input.item.json;
const airtableRecordId = item._airtableRecordId || '';
const fields = item._fields || {};

if (!airtableRecordId) {
  return { json: { ...item, _skipUpdate: true, _reason: 'No Airtable record ID found' } };
}

const payload = {
  records: [
    {
      id: airtableRecordId,
      fields: fields
    }
  ]
};

return { json: { ...item, _airtablePayload: JSON.stringify(payload) } };
